<template><section class="panel sequence-viz-cohort" data-testid="sequence-cohort"><h3>Species comparison · shared complete-population fingerprints</h3><p class="muted">One cohort, scope and source version drives PCA, distance and dispersion. Maximum 32 registered species. Missing inputs are listed explicitly.</p><div class="sequence-viz-controls"><label>Find registered species<input v-model="query" class="input" @input="search"/></label><button class="btn" :disabled="loading||preparing" @click="load">Update cohort</button><a :href="download">Cohort inputs / distance / linkage JSON</a></div><ul v-if="matches.length" class="sequence-viz-matches"><li v-for="s in matches" :key="s.species_id"><button class="btn subtle" @click="add(s.species_id)">{{ s.display_name||s.species_id }}</button></li></ul><div class="sequence-viz-controls"><button v-for="s in selected" :key="s" class="btn subtle" :disabled="loading||preparing" @click="selected=selected.filter(x=>x!==s)">{{ s.replaceAll('_',' ') }} ×</button></div><p v-if="error">{{ error }}</p><p v-if="cohort?.excluded_species?.length" class="sequence-viz-caption">Excluded: {{ cohort.excluded_species.map(s=>s.species_id+': '+s.reason_code).join('; ') }}</p><button v-if="cohort?.excluded_species?.some(s=>s.needs_preparation)" class="btn subtle" :disabled="preparing" @click="prepare">{{ preparing?'Preparing selected species…':'Prepare missing selected species' }}</button><template v-if="cohort"><p class="sequence-viz-caption">Included {{ cohort.species.length }} of {{ cohort.selected_species.length }} selected species, using one scope and one cohort identity.</p><SequenceFigure v-for="id in ids" :key="id" :figure="figure(id)" :chart-id="id" :species-id="speciesId" :omics="omics" :scope="scope"/><div class="table-wrap"><table><thead><tr><th>Species</th><th v-for="f in cohort.fields" :key="f">{{ f }}</th></tr></thead><tbody><tr v-for="(s,i) in cohort.species" :key="s"><td>{{ s }}</td><td v-for="(f,j) in cohort.fields" :key="f">{{ fmt(cohort.raw_means[i][j]) }} (n={{ cohort.counts[i][f] }})</td></tr><tr><td>Raw SD</td><td v-for="(x,j) in cohort.raw_sd" :key="j">{{ fmt(x) }}</td></tr><tr><td>Raw range</td><td v-for="(x,j) in cohort.raw_range" :key="j">{{ fmt(x) }}</td></tr></tbody></table></div></template></section></template>
<script setup>
import {ref,computed,watch,onBeforeUnmount} from 'vue';import client from '../../api/client';import {sequenceGet,sequenceEnsure,sequenceExport} from '../../api/sequenceVisuals';import SequenceFigure from './SequenceFigure.vue';import {number as fmt} from '../../utils/sequenceFormat'
const props=defineProps({speciesId:String,omics:String,scope:String,manifest:Object});const query=ref(''),matches=ref([]),selected=ref([]),initialized=ref(false),cohort=ref(null),loading=ref(false),preparing=ref(false),error=ref('');let seq=0,controller,searchController,searchSeq=0,timer,prepareController,prepareSeq=0
const ids=computed(()=>props.omics==='genome'?['GD21','GD22','GS02']:['TD14','TD15','TS02']);const download=computed(()=>sequenceExport(props.speciesId,props.omics,{scope:props.scope,kind:'cohort',species:selected.value.join(','),artifact_version:props.manifest.artifact_version}))
function figure(id){const type=id===ids.value[0]?'species_fingerprint_pca':id===ids.value[1]?'species_distance':'species_dispersion';return {...props.manifest,chart_id:id,title:type.replaceAll('_',' '),status:type==='species_fingerprint_pca'?cohort.value.pca.status:cohort.value.species.length>=2?'available':'unavailable',coverage:{n_source:cohort.value.species.length},data:{kind:type,cohort:cohort.value}}}
async function load(){const current=++seq;controller?.abort();controller=new AbortController();loading.value=true;try{const r=await sequenceGet(props.speciesId,props.omics,'cohort/',{scope:props.scope,artifact_version:props.manifest.artifact_version,...(initialized.value?{species:selected.value.join(',')}:{})},{signal:controller.signal});if(seq!==current)return;cohort.value=r;selected.value=r.selected_species;initialized.value=true;error.value=''}catch(e){if(seq===current&&!controller.signal.aborted)error.value=e.message}finally{if(seq===current)loading.value=false}}
async function search(){const current=++searchSeq;searchController?.abort();searchController=new AbortController();if(query.value.length<2){matches.value=[];return}try{const r=await client.get('/stoichdb/species/',{params:{q:query.value,page_size:20},signal:searchController.signal});if(current===searchSeq){const d=r.data.data;matches.value=d.results||d.items||[]}}catch(e){if(current===searchSeq&&!searchController.signal.aborted)error.value=e.message}}
function add(s){if(loading.value||preparing.value)return;if(!selected.value.includes(s)&&selected.value.length<32)selected.value.push(s);matches.value=[]}
async function prepare(){
 const current=++prepareSeq;prepareController?.abort();prepareController=new AbortController();const signal=prepareController.signal,mode=props.omics,scope=props.scope
 preparing.value=true;error.value='';const jobs=[]
 try{
  for(const s of cohort.value.excluded_species.filter(s=>s.needs_preparation)){const r=await sequenceEnsure(s.species_id,mode,scope,{signal});if(current!==prepareSeq)return;if(r.request_id)jobs.push({species:s.species_id,id:r.request_id,retries:0});else if(r.readiness!=='ready')throw new Error(s.species_id+': '+(r.reason_code||r.readiness))}
  async function poll(){
   try{let pending=false;const failed=[]
    for(const job of jobs){const r=await sequenceGet(job.species,mode,`requests/${job.id}/`,{},{signal});if(current!==prepareSeq)return
     if(r.readiness==='interrupted'&&job.retries++<1){await sequenceEnsure(job.species,mode,scope,{signal});pending=true}
     else if(['queued','running'].includes(r.readiness))pending=true
     else if(r.readiness!=='ready')failed.push(job.species+': '+(r.error||r.reason_code||r.readiness))
    }
    if(pending){timer=setTimeout(poll,1500);return}
    preparing.value=false;await load();if(failed.length)error.value=failed.join('; ')
   }catch(e){if(current===prepareSeq&&!signal.aborted){error.value=e.message;preparing.value=false}}
  }
  await poll()
 }catch(e){if(current===prepareSeq&&!signal.aborted){error.value=e.message;preparing.value=false}}
}

watch(()=>[props.speciesId,props.omics,props.scope,props.manifest.artifact_version],()=>{prepareSeq++;prepareController?.abort();preparing.value=false;initialized.value=false;selected.value=[];cohort.value=null;clearTimeout(timer);load()},{immediate:true});onBeforeUnmount(()=>{seq++;searchSeq++;prepareSeq++;prepareController?.abort();clearTimeout(timer);controller?.abort();searchController?.abort()})
</script>
